begin;
select plan(10);
insert into auth.users(id,email) values ('00000000-0000-0000-0000-0000000000a1','reconcile-a@x.com'),('00000000-0000-0000-0000-0000000000b1','reconcile-b@x.com');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-0000000000a1',true);
set local role authenticated;
select lives_ok($$select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','steps','[{"date":"2026-10-25","value":100000}]','{}','[]','{}')$$,'uncapped Health write succeeds');
select lives_ok($$select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','steps','[{"date":"2026-10-25","value":100000}]','{}','[]','{}')$$,'retry is idempotent');
select is((select count(*) from public.daily_metrics where date='2026-10-25'),1::bigint,'one row after retry');
select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000002','steps','[]','{2026-10-25}','[]','{}');
select is((select count(*) from public.daily_metrics where date='2026-10-25'),1::bigint,'another device cannot erase the row');
select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','steps','[]','{2026-10-25}','[]','{}');
select is((select count(*) from public.daily_metrics where date='2026-10-25'),0::bigint,'own tombstone clears the derived row');
insert into public.daily_metrics(user_id,date,metric,value,source) values(auth.uid(),'2026-10-25','steps',7,'manual');
select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','steps','[{"date":"2026-10-25","value":1000}]','{2026-10-25}','[]','{}');
select is((select value from public.daily_metrics where date='2026-10-25'),7::numeric,'manual override survives writes/deletes');
select throws_ok($$select public.apply_health_changes('00000000-0000-0000-0000-0000000000b1','00000000-0000-0000-0000-000000000001','steps','[]','{}','[]','{}')$$,'P0001','Health account changed','captured owner cannot change');
select throws_ok($$select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','sleep','[{"date":"2026-10-25","value":60}]','{}','[]','{}')$$,'P0001','missing sleep window','invalid sleep is rejected');
select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','weight','[]','{}','[{"measured_at":"2020-01-01T12:00:00Z","kg":80.125}]','{}');
select is((select kg from public.weight_measurements where measured_at='2020-01-01T12:00:00Z'),80.125::numeric,'old weight retains exact precision');
select public.apply_health_changes(auth.uid(),'00000000-0000-0000-0000-000000000001','weight','[]','{}','[]','{2020-01-01T12:00:00Z}');
select is((select count(*) from public.weight_measurements),0::bigint,'explicit weight deletion clears own source');
select * from finish();
rollback;
